// MIT. Portable capture refresh packets around the original HAR workspace store.
import { constants as C } from 'node:fs';
import { open, lstat, mkdir, rename, rm, readdir } from 'node:fs/promises';
import { resolve, dirname, basename, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import {
  prepare, openWorkspace, readRevision, readRegular, copyWorkspace,
  inspectWorkspace, saveReview, exportReview, digest,
} from './store.mjs';
import { canonical } from './model.mjs';
import { createRefreshPlan, REFRESH_SCHEMA } from './refresh-model.mjs';

const MAX_JSON = 4 * 1024 * 1024;
const MAX_REPORT = 32 * 1024 * 1024;
const FILES = ['change-report.json', 'draft.json', 'review.html'];
const json = bytes => JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes).replace(/^\uFEFF/, ''));
const encode = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const hash = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const identity = (previousSourceSha256, previousReviewSha256, candidateSourceSha256) => ({
  schema: REFRESH_SCHEMA, previousSourceSha256, previousReviewSha256, candidateSourceSha256,
});
async function syncDirectory(path) {
  const fd = await open(path, C.O_RDONLY);
  try { await fd.sync(); } finally { await fd.close(); }
}
async function privateDirectory(path) {
  const stat = await lstat(path);
  if (!stat.isDirectory() || stat.isSymbolicLink() || (stat.mode & 0o077))
    throw new Error('Refresh packet requires a private nonsymlink directory: ' + path);
}
async function writeNew(path, bytes) {
  const fd = await open(path, C.O_WRONLY | C.O_CREAT | C.O_EXCL | C.O_NOFOLLOW, 0o600);
  try { await fd.writeFile(bytes); await fd.sync(); } finally { await fd.close(); }
}
async function exists(path) {
  try { await lstat(path); return true; } catch (error) { if (error.code === 'ENOENT') return false; throw error; }
}
async function createDirectory(destination, build) {
  destination = resolve(destination);
  // Exclusive reservation and inode comparison preserve another writer's directory.
  await mkdir(destination, { mode: 0o700 });
  const reserved = await lstat(destination);
  const stage = join(dirname(destination), '.' + basename(destination) + '.' + randomUUID() + '.refresh-stage');
  let published = false;
  try {
    await mkdir(stage, { mode: 0o700 });
    await build(stage); await syncDirectory(stage);
    const current = await lstat(destination);
    if (current.ino !== reserved.ino || current.dev !== reserved.dev || (await readdir(destination)).length)
      throw new Error('Refresh destination reservation changed');
    await rename(stage, destination); published = true;
    await syncDirectory(dirname(destination));
  } catch (error) {
    if (!published) {
      await rm(stage, { recursive: true, force: true });
      try {
        const current = await lstat(destination);
        if (current.ino === reserved.ino && current.dev === reserved.dev && !(await readdir(destination)).length)
          await rm(destination, { recursive: true });
      } catch {}
    }
    throw error;
  }
}

export async function openRefresh(directory) {
  const root = resolve(directory); await privateDirectory(root);
  const manifest = json(await readRegular(join(root, 'refresh.json'), MAX_JSON, true));
  if (manifest.schema !== 'stellar.har-refresh-packet.v1' || !manifest.lineage ||
      manifest.lineage.schema !== REFRESH_SCHEMA ||
      !hash(manifest.lineage.previousSourceSha256) || !hash(manifest.lineage.previousReviewSha256) ||
      !hash(manifest.lineage.candidateSourceSha256))
    throw new Error('Invalid HAR refresh packet manifest');
  const expectedId = digest(Buffer.from(canonical(manifest.lineage)));
  if (manifest.operationId !== expectedId) throw new Error('Refresh operation identity changed');
  const previous = await openWorkspace(join(root, 'previous'));
  const candidate = await openWorkspace(join(root, 'candidate'));
  if (previous.manifest.sourceSha256 !== manifest.lineage.previousSourceSha256 ||
      candidate.manifest.sourceSha256 !== manifest.lineage.candidateSourceSha256)
    throw new Error('Refresh packet source edition changed');
  const saved = await readRevision(previous, manifest.lineage.previousReviewSha256);
  const computed = createRefreshPlan(previous.inventory, saved.review, candidate.inventory, saved.revision);
  const bytes = {};
  for (const filename of FILES) {
    const limit = filename === 'draft.json' ? MAX_JSON : MAX_REPORT;
    const descriptor = manifest.files?.[filename];
    if (!descriptor || !hash(descriptor.sha256) || !Number.isSafeInteger(descriptor.bytes) || descriptor.bytes < 1 || descriptor.bytes > limit)
      throw new Error('Invalid refresh file descriptor: ' + filename);
    bytes[filename] = await readRegular(join(root, filename), limit, true);
    if (bytes[filename].length !== descriptor.bytes || digest(bytes[filename]) !== descriptor.sha256)
      throw new Error('Retained refresh file changed: ' + filename);
  }
  const report = json(bytes['change-report.json']), draft = json(bytes['draft.json']);
  if (canonical(report) !== canonical(computed.report) || canonical(draft) !== canonical(computed.review))
    throw new Error('Refresh decisions or comparison disagree with their original source editions');
  return { root, manifest, previous, candidate, report, draft, bytes };
}

export function describeRefresh(packet, reused = false) {
  return {
    directory: packet.root, operationId: packet.manifest.operationId, reused,
    previousWorkspace: packet.previous.root, candidateWorkspace: packet.candidate.root,
    previousSourceSha256: packet.previous.manifest.sourceSha256,
    previousReviewSha256: packet.manifest.lineage.previousReviewSha256,
    candidateSourceSha256: packet.candidate.manifest.sourceSha256,
    reviewPage: join(packet.root, 'review.html'), draftFile: join(packet.root, 'draft.json'),
    reportFile: join(packet.root, 'change-report.json'), summary: packet.report.summary,
  };
}

export async function prepareRefresh({ workspace, revision, harFile, destination }) {
  const previous = await openWorkspace(workspace), saved = await readRevision(previous, revision);
  const candidateSha = digest(await readRegular(harFile));
  const lineage = identity(previous.manifest.sourceSha256, saved.revision, candidateSha);
  destination = resolve(destination);
  if (await exists(destination)) {
    const retained = await openRefresh(destination);
    if (canonical(retained.manifest.lineage) !== canonical(lineage))
      throw new Error('Refresh destination belongs to a different source/review selection');
    return describeRefresh(retained, true);
  }
  await createDirectory(destination, async stage => {
    await copyWorkspace(previous.root, join(stage, 'previous'));
    await prepare(harFile, join(stage, 'candidate'));
    const before = await openWorkspace(join(stage, 'previous'));
    const candidate = await openWorkspace(join(stage, 'candidate'));
    if (candidate.manifest.sourceSha256 !== candidateSha) throw new Error('Candidate capture changed during refresh preparation');
    const original = await readRevision(before, saved.revision);
    const { report, review } = createRefreshPlan(before.inventory, original.review, candidate.inventory, original.revision);
    const draftBytes = encode(review), reportBytes = encode(report);
    if (draftBytes.length > MAX_JSON || reportBytes.length > MAX_REPORT)
      throw new Error('Refresh exceeds the original review or comparison size limit');
    const manifest = {
      schema: 'stellar.har-refresh-packet.v1', operationId: digest(Buffer.from(canonical(lineage))), lineage, files: {},
    };
    const { renderRefreshReview } = await import('./refresh-review.mjs');
    const page = Buffer.from(await renderRefreshReview({ manifest, report, previous: before, candidate, draft: review }, review));
    if (page.length > MAX_REPORT) throw new Error('Offline refresh page exceeds 32 MiB');
    for (const [filename, bytes] of [['change-report.json', reportBytes], ['draft.json', draftBytes], ['review.html', page]]) {
      await writeNew(join(stage, filename), bytes);
      manifest.files[filename] = { sha256: digest(bytes), bytes: bytes.length };
    }
    await writeNew(join(stage, 'refresh.json'), encode(manifest));
    await openRefresh(stage);
  });
  return describeRefresh(await openRefresh(destination));
}

export async function inspectRefresh(directory) {
  const packet = await openRefresh(directory);
  const candidate = await inspectWorkspace(packet.candidate.root);
  return { ...describeRefresh(packet), candidateReviews: candidate.reviews,
    changedOperations: packet.report.operations.filter(row => row.status !== 'carried').map(row => ({
      operationId: row.operationId, method: row.method, path: row.path, status: row.status,
      changedSections: row.changes.map(change => change.section),
    })),
    ambiguousGroups: packet.report.ambiguous,
  };
}

function requireLineage(packet, review) {
  if (review.sourceSha256 !== packet.candidate.manifest.sourceSha256 ||
      canonical(review['x-har-refresh']) !== canonical(packet.manifest.lineage))
    throw new Error('Decisions must retain this refresh packet source/review lineage');
}

export async function saveRefreshReview(directory, decisionFile) {
  const packet = await openRefresh(directory);
  const bytes = await readRegular(decisionFile, MAX_JSON);
  const review = json(bytes); requireLineage(packet, review);
  // Snapshot the caller's exact bytes before the native writer reads its input.
  const temporary = join(packet.root, '.decisions.' + randomUUID() + '.json');
  await writeNew(temporary, bytes);
  try {
    const saved = await saveReview(packet.candidate.root, temporary);
    return { ...saved, directory: packet.root, operationId: packet.manifest.operationId,
      workspace: packet.candidate.root, previousReviewSha256: packet.manifest.lineage.previousReviewSha256 };
  } finally { await rm(temporary, { force: true }); }
}

export async function writeRefreshPage(directory, destination, revision) {
  const packet = await openRefresh(directory);
  const review = revision ? (await readRevision(packet.candidate, revision)).review : packet.draft;
  requireLineage(packet, review);
  const { renderRefreshReview } = await import('./refresh-review.mjs');
  const bytes = Buffer.from(await renderRefreshReview(packet, review));
  if (bytes.length > MAX_REPORT) throw new Error('Offline refresh page exceeds 32 MiB');
  await writeNew(resolve(destination), bytes);
  return { reviewPage: resolve(destination), operationId: packet.manifest.operationId,
    candidateSourceSha256: packet.candidate.manifest.sourceSha256, revision: revision || null };
}

export async function exportRefresh(directory, revision, destination) {
  const packet = await openRefresh(directory);
  requireLineage(packet, (await readRevision(packet.candidate, revision)).review);
  return { ...(await exportReview(packet.candidate.root, revision, destination)),
    operationId: packet.manifest.operationId, previousReviewSha256: packet.manifest.lineage.previousReviewSha256 };
}

export async function packageRefresh({ directory, revision, planFile, parent, name, operationPolicy }) {
  const packet = await openRefresh(directory);
  requireLineage(packet, (await readRevision(packet.candidate, revision)).review);
  const { saveHarMerchant } = await import('./merchant.mjs');
  return saveHarMerchant({ workspace: packet.candidate.root, revision, planFile, parent, name, operationPolicy });
}

export async function copyRefresh(directory, destination) {
  const packet = await openRefresh(directory); destination = resolve(destination);
  if (destination === packet.root) throw new Error('Choose a new receiving packet directory');
  await createDirectory(destination, async stage => {
    await copyWorkspace(packet.previous.root, join(stage, 'previous'));
    await copyWorkspace(packet.candidate.root, join(stage, 'candidate'));
    for (const filename of FILES) await writeNew(join(stage, filename), packet.bytes[filename]);
    await writeNew(join(stage, 'refresh.json'), encode(packet.manifest));
    await openRefresh(stage);
  });
  return describeRefresh(await openRefresh(destination));
}

// MIT. Offline operator review: no server, external scripts, source body or credential values.
import { readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const hash = text => createHash('sha256').update(text).digest('base64');
const safeJson = value => JSON.stringify(value).replace(/</g, '\\u003c').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
export async function renderReview(inventory, review) {
  const css=await readFile(new URL('./review.css',import.meta.url),'utf8');
  const model = (await readFile(new URL('./model.mjs', import.meta.url), 'utf8')).replace(/^export /gm, '');
  const ui=(await readFile(new URL('./ui.js',import.meta.url),'utf8')).replace(/^import[^\n]*;\n/gm,'').replace(/^export /gm,'');
  const script = model+'\n'+ui+'\nmountHarReview({root:document,initial:JSON.parse(document.getElementById("source-data").textContent)});\n';
  const payload = safeJson({ inventory, review });
  const policy = `default-src 'none'; script-src 'sha256-${hash(script)}' 'sha256-${hash(payload)}'; style-src 'sha256-${hash(css)}'; connect-src 'none'; img-src 'none'; base-uri 'none'; form-action 'none'; object-src 'none'`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="${policy}"><title>Stellar Forge · Captured API review</title><style>${css}</style></head><body>
<header><h1>Captured API review</h1><p class="muted">Stellar Forge · HAR source onboarding</p><p id="capture-summary"></p><small>Original source SHA256: <code id="source-hash"></code></small><p>This private review contains request names and observed schemas, never recorded credential or body values. Review paths and field names before sharing. Keep the original HAR workspace private.</p></header>
<main><section><h2>API source definition</h2><div class="header-fields"><label class="field"><span>Source origin URL (ending in /)</span><input id="merchant" list="source-origins" placeholder="https://api.example/"><datalist id="source-origins"></datalist></label><label class="field"><span>API title</span><input id="title"></label><label class="field"><span>Version</span><input id="version"></label></div><div class="toolbar"><label class="file-label">Import decisions <input id="import-review" type="file" accept="application/json,.json"></label><button id="restore-draft">Restore browser draft</button><button id="export-draft">Download draft</button></div><p id="selection-summary"></p></section>
<div class="layout"><aside><h2>Observed operations</h2><input id="search" aria-label="Filter operations" placeholder="Filter method, path or origin"><p id="page"></p><div id="operations"></div><div class="toolbar"><button id="previous">Previous</button><button id="next">Next</button></div><details><summary>Rejected entries</summary><pre id="rejected"></pre></details></aside><div><div id="detail"></div><section><h2>Reviewed OpenAPI</h2><div class="toolbar"><button id="validate">Validate and preview</button><button id="download">Download reviewed decisions</button></div><p id="status" role="status">Select operations and complete their decisions.</p><pre id="preview"></pre></section></div></div></main>
<footer>Save the downloaded decisions with <code>starforge openapi har save --workspace PRIVATE_DIR --decisions har-decisions.json</code>. Export the returned immutable revision with <code>starforge openapi har export --workspace PRIVATE_DIR --revision SHA256 --out NEW_DIR</code>. Open that <code>openapi.json</code> in the existing merchant workspace, then set the separate public seller URL and payment terms there.</footer>
<script id="source-data" type="application/json">${payload}</script><script>${script}</script></body></html>`;
}

// MIT. Private exact-source HAR sessions; immutable reviews and create-only publication.
import { constants as C } from 'node:fs';
import { open, lstat, mkdir, rename, rm, readdir } from 'node:fs/promises';
import { resolve, dirname, basename, join } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { inspectHar, newReview, buildDocument, canonical } from './model.mjs';
export const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const encode = o => Buffer.from(JSON.stringify(o, null, 2) + '\n');
const json = bytes => JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes).replace(/^\uFEFF/, ''));
const MAX_SOURCE = 128 * 1024 * 1024;
const MAX_REVIEW = 4 * 1024 * 1024;
async function syncDirectory(path) { const fd = await open(path, C.O_RDONLY); try { await fd.sync(); } finally { await fd.close(); } }
export async function readRegular(path, max = MAX_SOURCE, privateFile = false) {
  const fd = await open(path, C.O_RDONLY | C.O_NOFOLLOW);
  try {
    const before = await fd.stat();
    if (!before.isFile() || before.size > max || before.size < 1) throw new Error('Expected a nonempty regular file within the input limit');
    if (privateFile && (before.mode & 0o077)) throw new Error(`Private file permissions required: ${basename(path)}`);
    // Bound the descriptor read even when another process appends during intake.
    const bytes = Buffer.alloc(before.size + 1); let n = 0;
    while (n < bytes.length) { const r = await fd.read(bytes, n, bytes.length - n, null); if (!r.bytesRead) break; n += r.bytesRead; }
    const after = await fd.stat();
    if (n !== before.size || after.size !== before.size || before.mtimeMs !== after.mtimeMs || before.ctimeMs !== after.ctimeMs)
      throw new Error('Input changed during read; retry from one stable capture');
    return bytes.subarray(0, n);
  } finally { await fd.close(); }
}
async function writeNew(path, bytes) {
  const fd = await open(path, C.O_WRONLY | C.O_CREAT | C.O_EXCL | C.O_NOFOLLOW, 0o600);
  try { await fd.writeFile(bytes); await fd.sync(); } finally { await fd.close(); }
}
async function absent(path) { try { await lstat(path); throw new Error(`Destination already exists: ${path}`); } catch (e) { if (e.code !== 'ENOENT') throw e; } }
async function privateDirectory(path) {
  const stat = await lstat(path);
  if (!stat.isDirectory() || stat.isSymbolicLink() || (stat.mode & 0o077)) throw new Error(`Use a private nonsymlink directory: ${path}`);
}
async function newDirectory(destination, build) {
  destination = resolve(destination); await absent(destination);
  // Reserve the destination using exclusive mkdir, so another writer can never be replaced by rename.
  await mkdir(destination, { mode: 0o700 });
  const reservation = await lstat(destination);
  const stage = join(dirname(destination), `.${basename(destination)}.${randomUUID()}.stage`);
  await mkdir(stage, { mode: 0o700 });
  try {
    const result = await build(stage);
    await syncDirectory(stage);
    const now = await lstat(destination);
    if (now.ino !== reservation.ino || now.dev !== reservation.dev || (await readdir(destination)).length)
      throw new Error('Destination reservation changed');
    await rename(stage, destination); await syncDirectory(dirname(destination));
    return result;
  } catch (e) {
    await rm(stage, { recursive: true, force: true });
    try { const now = await lstat(destination); if (now.ino === reservation.ino && now.dev === reservation.dev && !(await readdir(destination)).length) await rm(destination, { recursive: true }); } catch {}
    throw e;
  }
}
export async function prepare(harFile, destination) {
  const source = await readRegular(harFile), sourceSha256 = digest(source);
  const inventory = inspectHar(json(source), sourceSha256), inventoryBytes = encode(inventory);
  const manifest = { schema: 'stellar.har-workspace.v1', sourceSha256, sourceBytes: source.length, inventorySha256: digest(inventoryBytes),
    captureFormat: 'HAR 1.2', privacy: 'Original capture may contain credentials and personal data; keep this entire workspace private.' };
  await newDirectory(destination, async stage => {
    await writeNew(join(stage, 'source.har'), source); await writeNew(join(stage, 'inventory.json'), inventoryBytes);
    await mkdir(join(stage, 'reviews'), { mode: 0o700 });
    await writeNew(join(stage, 'source.json'), encode(manifest));
  });
  return { workspace: resolve(destination), ...manifest, groups: inventory.groups.length, rejected: inventory.rejected.length };
}
export async function openWorkspace(directory) {
  const root = resolve(directory); await privateDirectory(root);
  const manifest = json(await readRegular(join(root, 'source.json'), MAX_REVIEW, true));
  if (manifest.schema !== 'stellar.har-workspace.v1' || !/^[a-f0-9]{64}$/.test(manifest.sourceSha256)) throw new Error('Invalid HAR workspace manifest');
  const source = await readRegular(join(root, 'source.har'), MAX_SOURCE, true);
  if (digest(source) !== manifest.sourceSha256 || source.length !== manifest.sourceBytes) throw new Error('Original HAR source identity changed');
  const bytes = await readRegular(join(root, 'inventory.json'), MAX_SOURCE, true);
  if (digest(bytes) !== manifest.inventorySha256) throw new Error('Inventory identity changed');
  const inventory = json(bytes);
  // Inventory always comes from the original decoder; a replaced manifest cannot inject a different inventory.
  if (canonical(inventory) !== canonical(inspectHar(json(source), manifest.sourceSha256))) throw new Error('Inventory disagrees with the retained HAR source');
  await privateDirectory(join(root, 'reviews'));
  return { root, manifest, inventory, newReview: () => newReview(inventory) };
}
export async function readRevision(workspace, revision) {
  if (!/^[a-f0-9]{64}$/.test(revision)) throw new Error('Review revision must be a full SHA256');
  const bytes = await readRegular(join(workspace.root, 'reviews', revision + '.json'), MAX_REVIEW, true);
  if (digest(bytes) !== revision) throw new Error('Saved review identity changed');
  const review = json(bytes); buildDocument(workspace.inventory, review);
  return { bytes, review, revision };
}
export async function saveReview(directory, decisionFile) {
  const workspace = await openWorkspace(directory);
  const review = json(await readRegular(decisionFile, MAX_REVIEW));
  const document = buildDocument(workspace.inventory, review);
  const bytes = Buffer.from(canonical(review) + '\n'), revision = digest(bytes), target = join(workspace.root, 'reviews', revision + '.json');
  if (bytes.length > MAX_REVIEW) throw new Error('Review exceeds 4 MiB');
  const stage = target + '.' + randomUUID() + '.tmp';
  await writeNew(stage, bytes);
  try {
    // Exclusive hard-link publication makes concurrent equal saves idempotent without replacement.
    const { link } = await import('node:fs/promises');
    try { await link(stage, target); await syncDirectory(dirname(target)); }
    catch (e) { if (e.code !== 'EEXIST' || digest(await readRegular(target, MAX_REVIEW, true)) !== revision) throw e; }
  } finally { await rm(stage, { force: true }); }
  return { revision, operations: Object.values(document.paths).reduce((n, p) => n + Object.keys(p).length, 0), sourceSha256: workspace.manifest.sourceSha256 };
}
export async function exportReview(directory, revision, destination) {
  const workspace = await openWorkspace(directory), saved = await readRevision(workspace, revision);
  const document = buildDocument(workspace.inventory, saved.review);
  document['x-starforge-har'].reviewSha256 = revision;
  const spec = encode(document), decisions = saved.bytes;
  if (spec.length > MAX_REVIEW) throw new Error('Generated OpenAPI exceeds original importer 4 MiB source limit');
  const manifest = { schema: 'stellar.har-export.v1', sourceSha256: workspace.manifest.sourceSha256, reviewSha256: revision,
    files: { 'openapi.json': { sha256: digest(spec), bytes: spec.length }, 'review.json': { sha256: revision, bytes: decisions.length } },
    schemaAuthority: 'operator-reviewed-observations',
    nativeHandoff: 'Use openapi.json as the original backend source in the SF61 workspace. Configure the separate seller URL, payment terms and declared backend credential references there.' };
  await newDirectory(destination, async stage => {
    await writeNew(join(stage, 'openapi.json'), spec); await writeNew(join(stage, 'review.json'), decisions);
    await writeNew(join(stage, 'manifest.json'), encode(manifest));
  });
  return { output: resolve(destination), ...manifest };
}
export async function copyWorkspace(directory, destination) {
  const workspace = await openWorkspace(directory), revisions = (await readdir(join(workspace.root, 'reviews'))).filter(p => /^[a-f0-9]{64}\.json$/.test(p)).sort();
  // Read and verify every immutable revision before publishing the receiving directory.
  const selected = [];
  for (const filename of revisions) selected.push(await readRevision(workspace, filename.slice(0, -5)));
  await newDirectory(destination, async stage => {
    for (const f of ['source.har', 'inventory.json', 'source.json']) await writeNew(join(stage, f), await readRegular(join(workspace.root, f), MAX_SOURCE, true));
    await mkdir(join(stage, 'reviews'), { mode: 0o700 });
    for (const saved of selected) await writeNew(join(stage, 'reviews', saved.revision + '.json'), saved.bytes);
    await openWorkspace(stage);
  });
  return { workspace: resolve(destination), sourceSha256: workspace.manifest.sourceSha256, revisions: selected.map(x => x.revision) };
}
export async function inspectWorkspace(directory) {
  const w = await openWorkspace(directory), reviews = [];
  for (const filename of (await readdir(join(w.root, 'reviews'))).filter(p => /^[a-f0-9]{64}\.json$/.test(p)).sort()) {
    const r = await readRevision(w, filename.slice(0, -5));
    reviews.push({ revision: r.revision, operations: r.review.operations.filter(o => o.enabled).map(o => o.id) });
  }
  return { workspace: w.root, ...w.manifest, totalEntries: w.inventory.totalEntries, groups: w.inventory.groups.length, rejected: w.inventory.rejected, reviews };
}
export async function writeReviewPage(directory, destination, render, revision) {
  const w = await openWorkspace(directory), review = revision ? (await readRevision(w, revision)).review : w.newReview();
  const html = await render(w.inventory, review);
  await writeNew(resolve(destination), Buffer.from(html));
  return { reviewPage: resolve(destination), sourceSha256: w.manifest.sourceSha256, revision: revision || null };
}

// MIT. One native operation editor shared by the offline review and private console.
import { buildDocument, HAR_SCHEMA } from './model.mjs';

export function mountHarReview({root=document,initial,onSave,readDraft,writeDraft,onChange}={}) {
const doc=root.ownerDocument??document;
if(!initial?.inventory||!initial?.review)throw new TypeError('Open the original capture review.');
const originalReview=structuredClone(initial.review);
const inventory = initial.inventory, byId = new Map(inventory.groups.map(g => [g.id, g]));
let review = structuredClone(initial.review), selected = 0, page = 0;
const $ = id => root.querySelector('#'+id);
const storageKey = 'stellar.har.draft.' + inventory.sourceSha256;
const jsonText = value => JSON.stringify(value, null, 2);
