    if (sha(bytes) !== manifest[hashKey] || !same(JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes)), expected))
      throw new TypeError('Existing compiled export changed: ' + file + '. Preserve it and choose a new package name.');
  }
