export async function retainJsonrpcCommerce(file, reviewed, { resume = false } = {}) {
  absolute(file);
  need(Buffer.isBuffer(reviewed?.sourceBytes) && sha(reviewed.sourceBytes) === reviewed.sha256,
    'COMMERCE_JSONRPC_PLAN_CHANGED');
